import functools
import time

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            start_time = time.time()
            result = func(*args, **kwargs)
            end_time = time.time()
            execution_time = end_time - start_time
            if timeout is not None and execution_time > timeout:
                raise TimeoutError(f"Function {func.__name__} exceeded the timeout of {timeout} seconds.")
            return result
        wrapper.__metadata__ = metadata
        return wrapper
    return decorator

# Example usage:
@unit_of_work(metadata="Example metadata", timeout=2)
def example_function():
    time.sleep(1)
    return "Function executed successfully"

try:
    print(example_function())
except TimeoutError as e:
    print(e)

