import os
from typing import Dict, List

def map_states_to_paths(inventory: Dict[str, Dict], version: str) -> Dict[str, List[str]]:
    """
    Maps the logical paths of states from an inventory based on a given version.

    Args:
        inventory (Dict[str, Dict]): The inventory containing states and their versions.
        version (str): The version of the inventory to use.

    Returns:
        Dict[str, List[str]]: A dictionary mapping states to their file paths.
    """
    state_paths: Dict[str, List[str]] = {}

    for state, state_info in inventory.items():
        if state_info.get('version') == version:
            file_paths = []
            for root, _, files in os.walk(state_info['path']):
                for file in files:
                    if file.endswith('.json'):
                        file_paths.append(os.path.join(root, file))
            if file_paths:
                state_paths[state] = file_paths

    return state_paths

