from collections import defaultdict

def dictsum(dict_list):
    """
    Sum the values for each key across all dictionaries in the list.

    Args:
        dict_list (list of dict): A list of dictionaries where each dictionary contains key-value pairs.

    Returns:
        dict: A new dictionary with the summed values for each key.
    """
    if not dict_list:
        return {}

    result = defaultdict(int)
    for dictionary in dict_list:
        for key, value in dictionary.items():
            result[key] += value
    return dict(result)

