import os

def normalize_paths(paths: list[str]) -> list[str]:
    """
    Normalizes the paths by removing the trailing pathname separator if present.

    Args:
        paths (list[str]): A list of path strings.

    Returns:
        list[str]: A list of normalized paths.
    """
    if paths is None:
        return []

    normalized_paths = []
    for path in paths:
        if path and os.path.sep in path:
            if path[-1] == os.path.sep:
                normalized_paths.append(path[:-1])
            else:
                normalized_paths.append(path)
        else:
            normalized_paths.append(path)

    return normalized_paths
